rng = np.random.default_rng(42)  # reproducible teaching only; not for a real release
def dp_count(true_count, epsilon, sensitivity=1.0):
    if epsilon <= 0:
        raise ValueError('epsilon must be positive')
    return true_count + rng.laplace(0, sensitivity / epsilon)
noisy = pd.DataFrame({'true': counts_true})
for epsilon in (0.1, 1.0, 10.0):
    noisy[f'epsilon={epsilon:g}'] = [dp_count(n, epsilon) for n in counts_true]
print(noisy.round(2))
